CREATE ROLE atlas_upgrade_reader;
CREATE TABLE atlas_upgrade_secure(tenant name NOT NULL, payload text NOT NULL);
ALTER TABLE atlas_upgrade_secure ENABLE ROW LEVEL SECURITY;
CREATE POLICY atlas_security_policy ON atlas_upgrade_secure USING (tenant = current_user);
GRANT SELECT ON atlas_upgrade_secure TO atlas_upgrade_reader;
INSERT INTO atlas_upgrade_secure VALUES ('atlas_upgrade_reader', 'visible'), ('postgres', 'hidden');
SET ROLE atlas_upgrade_reader;
SELECT CASE WHEN count(*) = 1 AND min(payload) = 'visible'
  THEN 'ATLAS_SECURITY_PASS:lifecycle.upgrade'
  ELSE 'ATLAS_SECURITY_FAIL:lifecycle.upgrade' END
FROM atlas_upgrade_secure;
DO $$ BEGIN
  UPDATE atlas_upgrade_secure SET payload = 'forged';
  RAISE EXCEPTION 'update unexpectedly allowed';
EXCEPTION WHEN insufficient_privilege THEN
  RAISE NOTICE 'ATLAS_SECURITY_PASS:lifecycle.upgrade';
END $$;
RESET ROLE;

